-- Migration 006: forma obligatoria de `hash`/`prev_hash` en audit_log.
--
-- QUÉ CIERRA. Las capas 1-3 (privilegios, trigger de fila, trigger de sentencia)
-- impiden MODIFICAR o BORRAR asientos, que es la amenaza clásica. Ninguna
-- impedía **añadir** una fila que no proviene de `audit.append`: un `INSERT`
-- suelto entra sin más y su hash arbitrario rompe la cadena desde ese punto.
--
-- Ocurrió de verdad. Durante la revisión funcional aparecieron 25 filas con
-- `hash` = 'h1'…'h4', 'x1'…'x15' y `prev_hash` vacío, insertadas por SQL en el
-- registro de los tenants `demo` y `otra-entidad` para probar la propia
-- pantalla de auditoría. La consecuencia no es reparable: el registro es
-- append-only por Ley 594, así que esas filas NO se pueden borrar y la cadena
-- de `demo` queda rota desde ahí para siempre. La reverificación lo denuncia
-- —y hace bien—, pero el daño ya está hecho. Un registro legal que solo se
-- protege contra la modificación deja abierta la puerta de la contaminación.
--
-- QUÉ NO CIERRA, dicho explícitamente: esto NO impide que alguien con acceso
-- SQL inserte una fila con un hash bien formado. Lo que esta restricción
-- elimina es la contaminación ACCIDENTAL —la de los datos de prueba y los
-- scripts improvisados—, que es la que ha ocurrido y la que seguirá ocurriendo
-- mientras nada la rechace.
--
-- Aquí decía que una fila «con hash bien formado pero falso» la detecta la
-- reverificación. **Es falso**, y comprobarlo fue el hallazgo de B12: el hash
-- es un SHA-256 SIN SECRETO sobre los campos canónicos, así que quien puede
-- insertar puede además calcular el hash CORRECTO —`compute_hash` vive en la
-- librería compartida que importan los once servicios— y añadir un asiento
-- perfectamente encadenado. Se demostró contra el registro real, dentro de una
-- transacción revertida: 932 asientos íntegros, se añade uno forjado a nombre
-- de un usuario real, y la reverificación sigue diciendo 933 verificados y
-- CERO roturas.
--
-- Lo que la cadena SÍ garantiza, y no es poco: que la historia no se reescribe.
-- Modificar y borrar están cerrados por privilegios (el rol de aplicación no
-- los tiene) y la inserción RETROACTIVA es inalcanzable, porque colocar una
-- fila en mitad de la historia exigiría recalcular las siguientes, que es un
-- UPDATE. Lo que NO garantiza es la AUTENTICIDAD de un asiento nuevo, y ninguna
-- cadena de hash sin clave puede garantizarla: añadir es justamente la
-- operación que una cadena permite.
--
-- Cerrarlo es un cambio de diseño, no un parche, y queda declarado como tal:
-- sellar cada asiento con un HMAC cuya clave no tenga el rol de base de datos
-- —con la misma convivencia de formatos que ya se usa para los asientos que no
-- cubren su `ts`—, o anclar el extremo de la cadena fuera del sistema, que es
-- lo que ya hace el respaldo. Mientras tanto, «cadena íntegra» significa «no se
-- ha reescrito», que es exactamente lo que la pantalla de auditoría afirma.
--
-- POR QUÉ `NOT VALID`. Las 25 filas ya existen y no se pueden borrar. Una
-- restricción validada haría fallar la migración; `NOT VALID` se aplica a toda
-- fila NUEVA y deja en paz a las viejas — que es exactamente el reparto
-- correcto: el pasado es inmutable, el futuro queda protegido. No se valida
-- después a propósito: `VALIDATE CONSTRAINT` fracasaría siempre.
--
-- Verificado contra PostgreSQL 15 real (tabla PARTICIONADA, `relkind='p'`):
-- la restricción se propaga a las particiones — el rechazo llega desde
-- `audit_log_default` — y el control positivo confirma que una fila con hash
-- SHA-256 de 64 hex sigue entrando.
--
-- Idempotente: no hay ADD CONSTRAINT IF NOT EXISTS para CHECK en Postgres.
-- Se comprueba el catálogo antes de añadir. NO se DROPea-y-recrea como en otras
-- migraciones de CHECK: sobre una tabla particionada con particiones vivas, un
-- DROP transitorio abriría una ventana —por breve que sea— en la que el registro
-- legal admite basura, y eso es justo lo que esta migración viene a cerrar.

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
          FROM pg_constraint c
          JOIN pg_class t ON t.oid = c.conrelid
          JOIN pg_namespace n ON n.oid = t.relnamespace
         WHERE c.conname = 'chk_audit_log_hash_forma'
           AND t.relname = 'audit_log'
           AND n.nspname = 'public'
    ) THEN
        ALTER TABLE public.audit_log
            ADD CONSTRAINT chk_audit_log_hash_forma
            CHECK (
                hash ~ '^[0-9a-f]{64}$'
                AND (prev_hash IS NULL OR prev_hash ~ '^[0-9a-f]{64}$')
            )
            NOT VALID;
    END IF;
END
$$;

COMMENT ON CONSTRAINT chk_audit_log_hash_forma ON public.audit_log IS
    'Forma SHA-256 (64 hex) de hash/prev_hash. Cuarta capa de la defensa del '
    'registro: las tres anteriores impiden UPDATE/DELETE, esta impide INSERTAR '
    'un asiento que no venga de orpycamcp_common.audit.append. NOT VALID a '
    'propósito — las filas contaminadas anteriores son append-only y no se '
    'pueden borrar.';

-- >>> auth-service/global/007_rol_app_sin_credencial_publicada.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
--
-- Software libre: se distribuye bajo la Licencia Pública General Affero de GNU
-- (AGPL) versión 3 o posterior, conservando los términos de la GPL del Orfeo
-- original del que deriva. SIN GARANTÍA ALGUNA. Véase LICENSE.

-- ===========================================================================
-- El rol de aplicación no puede llevar una contraseña publicada
-- ===========================================================================
--
-- La migración 003 crea `orpycamcp_app` con `LOGIN PASSWORD
-- 'CHANGE_IN_PRODUCTION'`, y ese literal está en un repositorio público bajo
-- AGPL. La nota decía «DEBE cambiarse antes del primer despliegue productivo»,
-- pero **ningún servicio usa ese rol** —el `DATABASE_URL` de todos apunta al rol
-- de arranque— así que nadie tiene un motivo operativo para cambiarla: no falla
-- nada si se deja como está. Una credencial que solo protege un aviso escrito no
-- protege nada.
--
-- No es un rol inofensivo: tiene INSERT sobre `public.audit_log`, que es la
-- tabla GLOBAL con la traza de todas las entidades. Poder insertar ahí es poder
-- fabricar asientos de auditoría a nombre de cualquiera.
--
-- Se le quita la capacidad de conectar en vez de cambiarle la contraseña por
-- otra: cualquier valor que se escriba aquí vuelve a estar publicado el día que
-- se hace push. El rol sigue existiendo con sus permisos —para que el
-- endurecimiento previsto se pueda activar sin rehacerlo— pero el operador tiene
-- que habilitarlo a mano, con un secreto suyo:
--
--     ALTER ROLE orpycamcp_app LOGIN PASSWORD '<secreto del despliegue>';
--
-- Idempotente y sin efecto sobre un despliegue que YA lo habilitó con su propia
-- contraseña: solo actúa si la contraseña vigente es exactamente la publicada.

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'orpycamcp_app') THEN
        RETURN;
    END IF;

    -- Se retira el LOGIN sin condiciones, y es deliberado. Se comprobó que
    -- NINGÚN servicio conecta con este rol —`grep orpycamcp_app` sobre el
    -- repositorio entero solo devuelve su propia migración, y en la pila viva
    -- todas las conexiones son del rol de arranque—, así que quitárselo no deja
    -- a nadie fuera. Un despliegue que sí lo hubiera cableado con su propio
    -- secreto lo vuelve a habilitar con una línea, y el aviso se la da.
    --
    -- Se evitó la alternativa «cambiarlo solo si la contraseña sigue siendo la
    -- publicada»: comparar hashes de Postgres es frágil —md5 y SCRAM no se
    -- comparan igual— y una condición que no se puede justificar es peor que
    -- ninguna, porque decide en silencio por un motivo que nadie puede releer.
    ALTER ROLE orpycamcp_app NOLOGIN;

    -- El COMMENT va DENTRO del bloque, no como sentencia suelta: `COMMENT ON
    -- ROLE` sobre un rol inexistente aborta la migración entera, y «el rol no
    -- existe» es un estado alcanzable (una base donde 003 no llegó a aplicarse).
    -- Se detectó probando ese caso contra Postgres real, no leyendo el fichero.
    EXECUTE $c$
        COMMENT ON ROLE orpycamcp_app IS
            'Rol de minimo privilegio para audit_log (INSERT+SELECT). Sin LOGIN: '
            'el operador debe darle una contrasena propia antes de usarlo. Hoy '
            'ningun servicio conecta con el; ver la auditoria de segunda pasada.'
    $c$;

    RAISE NOTICE
        'orpycamcp_app queda SIN LOGIN: llevaba la contrasena publicada en el '
        'repositorio y ningun servicio lo usa. Para activarlo con un secreto '
        'propio: ALTER ROLE orpycamcp_app LOGIN PASSWORD ''<secreto>'';';
END;
$$;

-- >>> auth-service/global/008_rol_app_privilegios.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
--
-- Software libre: se distribuye bajo la Licencia Pública General Affero de GNU
-- (AGPL) versión 3 o posterior, conservando los términos de la GPL del Orfeo
-- original del que deriva. SIN GARANTÍA ALGUNA. Véase LICENSE.

-- ===========================================================================
-- Privilegios del rol de aplicación: separar QUIEN OPERA de QUIEN ESTRUCTURA
-- ===========================================================================
--
-- Hasta aquí todos los servicios conectaban con el rol de arranque, que Postgres
-- crea SUPERUSUARIO. Con ese rol, las tres capas que protegen `audit_log` no
-- protegen nada: la capa de privilegios la omite el superusuario por definición,
-- y así lo dice la propia migración 003. Un guardián de solo-anexar que descansa
-- sobre permisos que nadie retira es una declaración, no un control.
--
-- El reparto queda así:
--
--   • Rol PROPIETARIO (el de arranque): aplica migraciones, provisiona entidades
--     y crea particiones. Es quien ESTRUCTURA. Los servicios ya no lo usan; sus
--     runners leen `MIGRATIONS_DATABASE_URL`.
--
--   • Rol de APLICACIÓN (`orpycamcp_app`): lee y escribe filas. Es quien OPERA.
--     No puede crear ni alterar objetos, y sobre `audit_log` solo puede AÑADIR.
--
--   • (Corregido) Se declaró aquí una excepción para `tenant-service`, «sellado
--     con token interno y no enrutado por el gateway». La premisa era falsa:
--     /dependencias, /catalogos, /config, /business-days y /pinar SÍ van a ese
--     servicio. Hoy también conecta con este rol: `POST /tenants` ya no ejecuta
--     DDL (la provisión del esquema es de `scripts/init_tenant.py`, propietario).
--
-- Se comprobó midiendo, no estimando: el carril de integración de
-- document-service pasa 99 de 103 con este rol; los 4 restantes fallaban por
-- privilegios que necesita el PROPIETARIO (crear esquema, declarar una clave
-- foránea contra un catálogo de `public`), no la aplicación.

DO $$
DECLARE
    propietario TEXT := current_user;
    esquema     TEXT;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'orpycamcp_app') THEN
        RAISE NOTICE 'orpycamcp_app no existe; nada que conceder.';
        RETURN;
    END IF;

    EXECUTE format('GRANT CONNECT ON DATABASE %I TO orpycamcp_app', current_database());

    -- Esquemas que ya existen: `public` y los de cada entidad provisionada.
    FOR esquema IN
        SELECT nspname FROM pg_namespace
         WHERE nspname = 'public' OR nspname LIKE 'tenant\_%'
    LOOP
        EXECUTE format('GRANT USAGE ON SCHEMA %I TO orpycamcp_app', esquema);
        EXECUTE format(
            'GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA %I TO orpycamcp_app',
            esquema);
        EXECUTE format(
            'GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA %I TO orpycamcp_app', esquema);
        EXECUTE format(
            'GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA %I TO orpycamcp_app', esquema);
    END LOOP;

    -- ── Lo que aún no existe ────────────────────────────────────────────────
    --
    -- Conceder sobre lo existente NO basta, y es el error que más caro sale:
    -- la entidad que se da de alta mañana, y la tabla que añada la próxima
    -- migración, nacerían sin permisos y el fallo aparecería al primer uso en
    -- producción, no al desplegar. Se comprobó ejecutándolo: con los permisos
    -- concedidos sobre las 106 tablas existentes, todo seguía fallando en cuanto
    -- se creaba un esquema nuevo.
    --
    -- Los privilegios por omisión van SIN `IN SCHEMA`, o sea globales para todo
    -- lo que cree el propietario en cualquier esquema, presente o futuro. Es lo
    -- que hace que dar de alta una entidad no requiera acordarse de nada.
    EXECUTE format(
        'ALTER DEFAULT PRIVILEGES FOR ROLE %I '
        'GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO orpycamcp_app', propietario);
    EXECUTE format(
        'ALTER DEFAULT PRIVILEGES FOR ROLE %I '
        'GRANT USAGE, SELECT ON SEQUENCES TO orpycamcp_app', propietario);
    EXECUTE format(
        'ALTER DEFAULT PRIVILEGES FOR ROLE %I '
        'GRANT EXECUTE ON FUNCTIONS TO orpycamcp_app', propietario);

    RAISE NOTICE 'orpycamcp_app: privilegios de operación concedidos (propietario: %).',
        propietario;
END;
$$;

-- ---------------------------------------------------------------------------
-- La excepción: sobre la auditoría solo se AÑADE
-- ---------------------------------------------------------------------------
--
-- Los privilegios por omisión de arriba conceden UPDATE y DELETE sobre toda
-- tabla nueva, lo cual es correcto para las tablas de dominio y sería la ruina
-- para `audit_log`: cada partición mensual nueva nacería mutable. La excepción
-- se retira aquí para lo que ya existe, y se añade a `harden_audit_partition`
-- para lo que venga — que es donde ya vive el endurecimiento de cada partición,
-- en vez de en un segundo sitio que alguien tendría que recordar.
DO $$
DECLARE
    parte TEXT;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'orpycamcp_app') THEN
        RETURN;
    END IF;
    -- La tabla se comprueba además del rol: `REVOKE` sobre una relación
    -- inexistente aborta la migración entera, y «aún no existe» es un estado
    -- alcanzable en una base donde las migraciones previas no llegaron. Se
    -- detectó probándolo contra Postgres real, no leyendo el fichero.
    IF NOT EXISTS (
        SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
         WHERE n.nspname = 'public' AND c.relname = 'audit_log'
    ) THEN
        RAISE NOTICE 'public.audit_log no existe todavía; nada que revocar.';
        RETURN;
    END IF;
    REVOKE UPDATE, DELETE, TRUNCATE ON TABLE public.audit_log FROM orpycamcp_app;
    FOR parte IN
        SELECT c.relname
          FROM pg_class c
          JOIN pg_inherits i ON i.inhrelid = c.oid
          JOIN pg_class p ON p.oid = i.inhparent
         WHERE p.relname = 'audit_log'
    LOOP
        EXECUTE format(
            'REVOKE UPDATE, DELETE, TRUNCATE ON TABLE public.%I FROM orpycamcp_app', parte);
    END LOOP;
END;
$$;

-- ---------------------------------------------------------------------------
-- Y para las particiones que vengan
-- ---------------------------------------------------------------------------
--
-- `harden_audit_partition` retiraba UPDATE/DELETE/TRUNCATE de PUBLIC. Eso no
-- alcanza a `orpycamcp_app`, que los recibe por concesión DIRECTA vía los
-- privilegios por omisión: revocar de PUBLIC no toca lo concedido a un rol
-- nombrado. Sin esta línea, cada partición mensual nueva nacería mutable para
-- la aplicación y el guardián volvería a ser una declaración.
--
-- Se añade aquí, dentro de la función que el job ya llama, y no como un paso
-- más en el job: un endurecimiento que depende de que alguien recuerde
-- invocarlo es el que se olvida.
CREATE OR REPLACE FUNCTION public.harden_audit_partition(partition_name text)
RETURNS void
LANGUAGE plpgsql
AS $fn$
DECLARE
    _trig_trunc TEXT;
    _trig_mut   TEXT;
BEGIN
    IF partition_name !~ '^audit_log[a-z0-9_]*$' THEN
        RAISE EXCEPTION
            'harden_audit_partition: nombre de partición inválido: %. '
            'Debe empezar por audit_log y contener solo [a-z0-9_].', partition_name;
    END IF;

    EXECUTE format(
        'REVOKE UPDATE, DELETE, TRUNCATE ON TABLE public.%I FROM PUBLIC', partition_name);

    -- El rol de aplicación recibe UPDATE/DELETE por los privilegios por omisión
    -- (migración 008). Sobre la auditoría se retiran: solo se AÑADE.
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'orpycamcp_app') THEN
        EXECUTE format(
            'REVOKE UPDATE, DELETE, TRUNCATE ON TABLE public.%I FROM orpycamcp_app',
            partition_name);
    END IF;

    _trig_trunc := 'trg_' || partition_name || '_no_truncate';
    _trig_mut   := 'trg_' || partition_name || '_no_mutation';

    EXECUTE format('DROP TRIGGER IF EXISTS %I ON public.%I', _trig_trunc, partition_name);
    EXECUTE format(
        'CREATE TRIGGER %I BEFORE TRUNCATE ON public.%I '
        'FOR EACH STATEMENT EXECUTE FUNCTION public.reject_audit_log_mutation_d03()',
        _trig_trunc, partition_name);

    EXECUTE format('DROP TRIGGER IF EXISTS %I ON public.%I', _trig_mut, partition_name);
    EXECUTE format(
        'CREATE TRIGGER %I BEFORE UPDATE OR DELETE ON public.%I '
        'FOR EACH STATEMENT EXECUTE FUNCTION public.reject_audit_log_mutation_d03()',
        _trig_mut, partition_name);
END;
$fn$;

-- >>> auth-service/global/009_audit_chain_runs.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- 009 — Resultado de cada corrida de `app.ops.verify_audit_chains` (C18, ADR-041).
--
-- `/metrics` de auth-service NO ejecuta `verify_chain` (recorre el registro
-- entero): lee la última corrida COMPLETA que dejó el CLI de respaldo/cron aquí.
-- Es un agregado sin datos de tenant por fila, y NO es un asiento de la cadena:
-- escribirlo en `audit_log` movería el extremo que `backup.sh` ancla en la misma
-- corrida.
--
-- Solo se añade: una corrida pasada no se corrige ni se borra. `alcance` separa
-- la verificación completa (cuenta) de la parcial (`--slug` / `--excluir-prefijo`,
-- NO cuenta: verificó menos de lo que dice). Idempotente.

CREATE TABLE IF NOT EXISTS public.audit_chain_runs (
    id                 BIGSERIAL PRIMARY KEY,
    started_at         TIMESTAMPTZ NOT NULL,
    finished_at        TIMESTAMPTZ NOT NULL,
    alcance            TEXT        NOT NULL CHECK (alcance IN ('completo', 'parcial')),
    origen             TEXT        NOT NULL CHECK (origen IN ('backup', 'restore', 'cron', 'manual')),
    tenants            INT         NOT NULL CHECK (tenants >= 0),
    asientos           BIGINT      NOT NULL CHECK (asientos >= 0),
    roturas_nuevas     INT         NOT NULL CHECK (roturas_nuevas >= 0),
    roturas_declaradas INT         NOT NULL CHECK (roturas_declaradas >= 0),
    retrocesos         INT         NOT NULL CHECK (retrocesos >= 0),
    anclas_alteradas   INT         NOT NULL CHECK (anclas_alteradas >= 0),
    codigo_salida      SMALLINT    NOT NULL
);

-- Lo único que consulta /metrics: la última corrida completa.
CREATE INDEX IF NOT EXISTS ix_audit_chain_runs_completo
    ON public.audit_chain_runs (id DESC) WHERE alcance = 'completo';

-- Las `DEFAULT PRIVILEGES` de 008 conceden UPDATE/DELETE a toda tabla nueva del
-- propietario; aquí solo se añade (INSERT + SELECT). Mismo criterio que audit_log.
-- No se toca el rol: solo esta tabla. Condicional por si el rol aún no existe.
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'orpycamcp_app') THEN
        REVOKE UPDATE, DELETE, TRUNCATE ON TABLE public.audit_chain_runs FROM orpycamcp_app;
    END IF;
END;
$$;

