-- Global migration 005: `public` guarda SOLO lo global (ADR-002, addendum C-7 / SEG #12).
--
-- Las migraciones de tenant 005 (admin_audit), 006 (catálogos) y 007 (PINAR) corrieron
-- alguna vez con un `search_path` cuyo primer schema no existía: el CREATE TABLE cae en el
-- primero que SÍ existe, `public`. Quedaron 14 copias huérfanas de tablas de TENANT en
-- `public` (más la función de trigger de PINAR). Ninguna ruta las lee a propósito: con el
-- `search_path` de solo-el-tenant (C-7), una lectura sin tabla propia es
-- `UndefinedTable`, no un fallback silencioso a estas copias.
--
-- Lista estática: son nombres que solo existen en `migrations/tenant/`. Sin
-- compatibilidad con datos viejos: son copias, el dato vivo está en cada `tenant_*`.

DROP TABLE IF EXISTS
    public.pinar_seguimiento,
    public.pinar_priorizacion,
    public.pinar_proyecto_aspecto,
    public.pinar_proyecto,
    public.pinar_instrumento_ref,
    public.pinar_aspecto_critico,
    public.pinar_objetivo,
    public.pinar_eje,
    public.pinar_plan,
    public.mensajes_rapidos,
    public.soportes,
    public.formas_envio,
    public.causales,
    public.admin_audit
    CASCADE;

DROP FUNCTION IF EXISTS public.pinar_seguimiento_append_only();

-- >>> tenant-service/global/006_tenants_intelligence.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Global migration 006: elección de inteligencia por entidad (ADR-045 §4, fase D1).
--
-- Toda entidad nace en `local` y solo transmite PÚBLICA (1). RESERVADA (2) y
-- CLASIFICADA (3) salen después, con el acto del administrador. Los metadatos de
-- plantilla no salen hasta que ese mismo acto encienda el interruptor. El rol de
-- la aplicación ya tiene UPDATE sobre public.tenants: no hace falta grant nuevo.
--
-- Idempotente: una reejecución no vuelve a poner `local` a quien ya eligió `ppi`.

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
         WHERE table_schema = 'public'
           AND table_name = 'tenants'
           AND column_name = 'intelligence_provider'
    ) THEN
        ALTER TABLE public.tenants
            ADD COLUMN intelligence_provider TEXT NOT NULL DEFAULT 'local';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
         WHERE conname = 'tenants_intelligence_provider_chk'
           AND conrelid = 'public.tenants'::regclass
    ) THEN
        ALTER TABLE public.tenants
            ADD CONSTRAINT tenants_intelligence_provider_chk
            CHECK (intelligence_provider IN ('local', 'ppi'));
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
         WHERE table_schema = 'public'
           AND table_name = 'tenants'
           AND column_name = 'intelligence_levels'
    ) THEN
        ALTER TABLE public.tenants
            ADD COLUMN intelligence_levels SMALLINT[] NOT NULL DEFAULT '{1}';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
         WHERE conname = 'tenants_intelligence_levels_chk'
           AND conrelid = 'public.tenants'::regclass
    ) THEN
        ALTER TABLE public.tenants
            ADD CONSTRAINT tenants_intelligence_levels_chk
            CHECK (intelligence_levels <@ ARRAY[1, 2, 3]::smallint[]);
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
         WHERE table_schema = 'public'
           AND table_name = 'tenants'
           AND column_name = 'intelligence_send_metadata'
    ) THEN
        ALTER TABLE public.tenants
            ADD COLUMN intelligence_send_metadata BOOLEAN NOT NULL DEFAULT false;
    END IF;
END $$;

