-- Migración global (schema public): extensiones compartidas por todos los tenants.
--
-- Las extensiones se instalan una sola vez en `public` y se resuelven desde
-- cualquier schema tenant_{slug} porque `public` siempre está en el search_path
-- (ADR-002/012). No deben crearse por-tenant: provocaría copias redundantes.
--
--   pg_trgm   → índices GIN trigram para búsqueda difusa/prefijo (search-service)
--   unaccent  → normalización de acentos para FTS en español

CREATE EXTENSION IF NOT EXISTS pg_trgm WITH SCHEMA public;
CREATE EXTENSION IF NOT EXISTS unaccent WITH SCHEMA public;

-- >>> document-service/global/002_spanish_unaccent.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración global (schema public): configuración de búsqueda en español que
-- IGNORA LOS ACENTOS.
--
-- La extensión `unaccent` se instalaba desde el primer día (001_extensions.sql
-- lo dice: «normalización de acentos para FTS en español») y el ADR-014 la
-- declara parte de la decisión de búsqueda. Nunca llegó a usarse: tanto el
-- `search_vector` como la consulta seguían con la configuración `spanish` a
-- secas. El resultado, comprobado pulsando botones: buscar «certificacion»
-- devolvía CERO radicados mientras «certificación» devolvía tres. En un sistema
-- que usan funcionarios colombianos escribiendo deprisa, eso no es un caso
-- exótico — es el caso normal, y falla en silencio: la pantalla dice «Sin
-- resultados», que es indistinguible de «no existe».
--
-- Va en `public` y no por-tenant a propósito, igual que las extensiones: una
-- configuración de texto por entidad serían copias redundantes de lo mismo, y
-- las columnas generadas la referencian por nombre cualificado.

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_ts_config c
          JOIN pg_namespace n ON n.oid = c.cfgnamespace
         WHERE c.cfgname = 'spanish_unaccent' AND n.nspname = 'public'
    ) THEN
        CREATE TEXT SEARCH CONFIGURATION public.spanish_unaccent (COPY = pg_catalog.spanish);
        -- `unaccent` ANTES de `spanish_stem`: primero se quitan los acentos,
        -- después se reduce a la raíz. Al revés, la raíz conservaría el acento
        -- y el problema seguiría igual.
        ALTER TEXT SEARCH CONFIGURATION public.spanish_unaccent
            ALTER MAPPING FOR hword, hword_part, word
            WITH unaccent, spanish_stem;
    END IF;
END
$$;

-- >>> document-service/global/003_divipola.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración GLOBAL (E01, RF-RAD-05, 2026-08-30): catálogo DIVIPOLA del DANE
-- —división político-administrativa de Colombia— como vocabulario CERRADO para
-- la geografía de terceros y envíos.
--
-- ── Por qué un catálogo y no dos campos de texto ────────────────────────────
--
-- La migración `tenant/026` dejó `municipio` y `departamento` como TEXTO LIBRE.
-- Eso resolvía la mitad del problema de duplicación —la identidad del sujeto ya
-- va por documento— y dejaba abierta la otra mitad: **«Bogotá», «BOGOTA»,
-- «Bogota D.C.» y «Santa Fe de Bogotá» son cuatro municipios distintos** para
-- cualquier consulta, cualquier reporte y cualquier exportación.
--
-- Es exactamente la plaga que arrastraba el Orfeo original, vista desde el otro
-- lado: allí el mismo sujeto aparecía treinta veces «cambiando a veces una
-- tilde». Una restricción de unicidad no lo arregla, porque las cuatro escrituras
-- SON distintas y todas pasan. Lo único que lo cierra es que el municipio deje
-- de ser algo que se escribe y pase a ser algo que se ELIGE.
--
-- ── Global y no por tenant ──────────────────────────────────────────────────
--
-- DIVIPOLA es nacional: no lo edita la entidad, no varía entre entidades, y
-- replicar 1.135 filas por cada schema `tenant_*` sería copiar un dato que
-- nadie puede divergir. Vive en `public` junto a las extensiones y al
-- diccionario `spanish_unaccent`, y las migraciones globales se aplican ANTES
-- que las de tenant (`migrations/runner.py`), que es lo que permite a la 027
-- apuntar sus claves foráneas aquí.
--
-- ── Procedencia y fecha de corte (se declara, no se disimula) ───────────────
--
-- Los 33 departamentos y los 1.135 municipios se extrajeron del volcado
-- `20170810_baseOrfeo7.sql` del Orfeo de ICETEX, que ya traía el catálogo con
-- sus códigos DIVIPOLA correctos y sus nombres acentuados (verificado contra
-- casos conocidos: 05001 Medellín, 11001 Bogotá, 27150 Carmen del Darién,
-- 91001 Leticia). Los nombres de DEPARTAMENTO se reescribieron a mano con su
-- denominación oficial, porque el volcado los traía en mayúsculas sin tildes y
-- con «11 D.C.» en lugar de «Bogotá, D.C.».
--
-- **La fecha de corte del catálogo es 2017**, y desde entonces DIVIPOLA ha
-- tenido cambios menores (p. ej. 94343 figura aquí como «Guaviare» y hoy es el
-- municipio de Barrancominas, erigido en 2019). Se declara porque importa saber
-- qué se está usando; la actualización es un `INSERT ... ON CONFLICT` sobre
-- estas mismas tablas y por eso la carga de abajo es idempotente y
-- reejecutable. Un municipio que deja de existir NO se borra —hay envíos
-- históricos que lo nombran— sino que se marca `vigente = false`.

CREATE TABLE IF NOT EXISTS public.divipola_departamento (
    codigo  CHAR(2)  NOT NULL PRIMARY KEY,
    nombre  TEXT     NOT NULL,
    -- Un departamento no desaparece del catálogo aunque deje de estar vigente:
    -- los envíos hechos cuando existía lo siguen nombrando.
    vigente BOOLEAN  NOT NULL DEFAULT true,
    CONSTRAINT divipola_departamento_codigo_check CHECK (codigo ~ '^[0-9]{2}$')
);

COMMENT ON TABLE public.divipola_departamento IS
    'Departamentos DIVIPOLA (DANE). Catálogo nacional, global al despliegue: no lo edita la entidad. Corte 2017, actualizable por INSERT ... ON CONFLICT.';

CREATE TABLE IF NOT EXISTS public.divipola_municipio (
    codigo              CHAR(5) NOT NULL PRIMARY KEY,
    departamento_codigo CHAR(2) NOT NULL
        REFERENCES public.divipola_departamento (codigo),
    nombre              TEXT    NOT NULL,
    vigente             BOOLEAN NOT NULL DEFAULT true,
    CONSTRAINT divipola_municipio_codigo_check CHECK (codigo ~ '^[0-9]{5}$'),
    -- El código DIVIPOLA de municipio LLEVA DENTRO el de su departamento. Que
    -- la base lo compruebe hace imposible la fila incoherente —un municipio
    -- colgado de otro departamento—, que es el error que una cascada mal
    -- programada produce en silencio.
    CONSTRAINT divipola_municipio_pertenencia_check
        CHECK (left(codigo, 2) = departamento_codigo)
);

COMMENT ON TABLE public.divipola_municipio IS
    'Municipios DIVIPOLA (DANE). El código incluye el del departamento y un CHECK lo impone: la pertenencia no depende de quien inserta.';

CREATE INDEX IF NOT EXISTS ix_divipola_municipio_departamento
    ON public.divipola_municipio (departamento_codigo)
    WHERE vigente;

-- ── Carga del catálogo ──────────────────────────────────────────────────────
--
-- Idempotente a propósito: `ON CONFLICT ... DO UPDATE` deja que reejecutar la
-- migración con un volcado más reciente actualice los nombres sin tocar nada
-- más, y sin perder las filas que ya no vengan en el origen (que se marcarían
-- `vigente = false` a mano, nunca borrando).

ON CONFLICT (codigo) DO UPDATE SET nombre = EXCLUDED.nombre;

ON CONFLICT (codigo) DO UPDATE SET nombre = EXCLUDED.nombre;

-- >>> document-service/global/004_divipola_fuente_oficial.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración GLOBAL (E01, RF-RAD-05, 2026-08-30): el catálogo DIVIPOLA pasa a la
-- FUENTE OFICIAL del DANE. Corrige la carga de `003_divipola.sql`.
--
-- ── Lo que se dio por bueno y no lo era ─────────────────────────────────────
--
-- La 003 cargó el catálogo desde el volcado del Orfeo de ICETEX y lo verificó
-- contra **cuatro casos conocidos** —05001 Medellín, 11001 Bogotá, 27150 Carmen
-- del Darién, 91001 Leticia—. Los cuatro daban bien. El resto no se comprobó.
--
-- Un cotejo mecánico contra el catálogo del DANE (1.122 entidades: 1.103
-- municipios, 18 áreas no municipalizadas y 1 isla) encontró **38 diferencias**
-- en las 1.135 filas cargadas:
--
--   * **15 nombres distintos**, y uno de ellos no es una variante de escritura
--     sino un municipio EQUIVOCADO: el volcado traía `(muni_codi=21, dpto=05,
--     'PASTO')`, es decir **Pasto colgado de Antioquia** con el código que
--     pertenece a Alejandría. Pasto es 52001, en Nariño. En la misma línea,
--     Alejandría figuraba en 05076, que no es su código.
--   * **18 códigos que DIVIPOLA no reconoce** — Sincelejo en el 15 (Boyacá),
--     Solano en 18765 en vez de 18756, corregimientos y veredas mezclados con
--     municipios: la basura acumulada de una instalación real.
--   * **5 municipios que faltaban**, incluidos dos posteriores al corte: Tuchín
--     (23815) y **Nuevo Belén de Bajirá** (27493), segregado de Riosucio e
--     incorporado por el DANE en 2023.
--
-- Los 33 departamentos sí coincidían: se habían escrito a mano contra la
-- denominación oficial, que es justamente lo que no se hizo con los municipios.
--
-- ── Por qué una migración nueva y no editar la 003 ──────────────────────────
--
-- El libro `public.schema_migrations` identifica cada migración por
-- `(servicio, nombre_archivo)` y **no guarda hash del contenido**: reescribir la
-- 003 dejaría a cualquier despliegue que ya la aplicó con el catálogo malo y sin
-- que nada avisara. Es el fallo mudo que este proyecto ya conoce.
--
-- ── Origen y actualización ──────────────────────────────────────────────────
--
-- Fuente: portal de Datos Abiertos del Estado colombiano, conjunto DIVIPOLA del
-- DANE (`datos.gov.co`, recurso `gdxc-w37w`), consultado el 2026-08-30. La carga
-- vuelve a ser idempotente por la misma razón que la 003: actualizar el catálogo
-- con una versión posterior es reejecutar este mismo tipo de archivo.
--
-- Un código que el DANE no reconoce **no se borra**: se marca `vigente = false`.
-- Borrarlo rompería cualquier ficha que ya lo apuntara —y la política de no
-- borrar un municipio suprimido la declaró la propia 003—. Los `vigente = false`
-- desaparecen de la cascada, que solo lista los vigentes, pero siguen
-- resolviendo el nombre de un envío histórico.

ON CONFLICT (codigo) DO UPDATE
    SET nombre = EXCLUDED.nombre,
        departamento_codigo = EXCLUDED.departamento_codigo,
        vigente = true;

-- Los códigos que el volcado traía y NO existen en DIVIPOLA se retiran de
-- circulación SIN borrarlos: es la política que la propia 003 declaró para un
-- municipio suprimido, y borrar rompería cualquier ficha que ya los apuntara.
UPDATE public.divipola_municipio SET vigente = false
 WHERE codigo NOT IN (
    '05001', '05002', '05004', '05021', '05030', '05031', '05034', '05036', '05038', '05040',
    '05042', '05044', '05045', '05051', '05055', '05059', '05079', '05086', '05088', '05091',
    '05093', '05101', '05107', '05113', '05120', '05125', '05129', '05134', '05138', '05142',
    '05145', '05147', '05148', '05150', '05154', '05172', '05190', '05197', '05206', '05209',
